const body = $input.first().json.body || $input.first().json;
const mensaje = body.mensaje || body.message || '';
const sessionId = body.session_id || body.sessionId || 'default-session';

if (!mensaje.trim()) {
  throw new Error('El campo mensaje es obligatorio');
}

return [{
  json: {
    mensaje: mensaje.trim(),
    sessionId: sessionId,
    timestamp: new Date().toISOString()
  }
}];

const inputData = $('Validar Input').item.json;

// El agente devuelve array - buscar el primer item con JSON válido en 'output'
const items = $input.all();
let clasificacion = { herramienta: 'ninguna', parametros: {}, razon: '' };

for (const item of items) {
  const raw = item.json.output || item.json.text || item.json.response || '';
  try {
    const parsed = JSON.parse(raw.trim());
    if (parsed.herramienta && parsed.herramienta !== 'ninguna') {
      clasificacion = parsed;
      break; // Encontrado, salir del bucle
    }
  } catch(e) {
    continue;
  }
}

return [{
  json: {
    mensaje:             inputData.mensaje,
    session_id:          inputData.session_id,
    timestamp:           inputData.timestamp,
    herramienta:         clasificacion.herramienta  || 'ninguna',
    parametros:          clasificacion.parametros   || {},
    razon_clasificacion: clasificacion.razon        || ''
  }
}];

const clima = $json;
const geo = $('Extraer Coordenadas').item.json.geo;
const inputData = $('Parsear Intencion').item.json;

const wmo = {0:'Despejado',1:'Mayormente despejado',2:'Parcialmente nublado',3:'Nublado',45:'Niebla',51:'Llovizna leve',61:'Lluvia leve',63:'Lluvia moderada',65:'Lluvia intensa',71:'Nieve leve',80:'Chubascos',95:'Tormenta',99:'Tormenta con granizo'};

const c = clima.current;
const d = clima.daily;
const estado = wmo[c.weather_code] || ('Codigo ' + c.weather_code);

const contexto = 'Ciudad: ' + geo.nombre + ', ' + geo.pais + '\nTemperatura: ' + c.temperature_2m + 'C (sensacion ' + c.apparent_temperature + 'C)\nViento: ' + c.wind_speed_10m + ' km/h\nHumedad: ' + c.relative_humidity_2m + '%\nEstado: ' + estado + '\nProximos 3 dias:\n- Hoy: ' + d.temperature_2m_min[0] + 'C - ' + d.temperature_2m_max[0] + 'C | Lluvia: ' + d.precipitation_sum[0] + 'mm\n- Manana: ' + d.temperature_2m_min[1] + 'C - ' + d.temperature_2m_max[1] + 'C | Lluvia: ' + d.precipitation_sum[1] + 'mm\n- Pasado: ' + d.temperature_2m_min[2] + 'C - ' + d.temperature_2m_max[2] + 'C | Lluvia: ' + d.precipitation_sum[2] + 'mm';

return [{
  json: {
    mensaje: inputData.mensaje,
    session_id: inputData.session_id,
    herramienta: inputData.herramienta,
    contexto_api: contexto
  }
}];

const inputData = $('Normalizar Pais').item.json;
const paises = Array.isArray($json) ? $json : [$json];
const p = paises[0];

const nombre = (p.translations && p.translations.spa) ? p.translations.spa.common : (p.name ? p.name.common : 'Desconocido');
const capital = (p.capital && p.capital[0]) ? p.capital[0] : 'Sin datos';
const poblacion = p.population ? p.population.toLocaleString('es-ES') : 'Sin datos';
const monedas = p.currencies ? Object.values(p.currencies).map(function(m) { return m.name + ' (' + (m.symbol || '') + ')'; }).join(', ') : 'Sin datos';
const idiomas = p.languages ? Object.values(p.languages).join(', ') : 'Sin datos';
const superficie = p.area ? p.area.toLocaleString('es-ES') + ' km2' : 'Sin datos';
const region = (p.subregion || '') + ', ' + (p.region || '');

const contexto = 'Pais: ' + nombre + '\nCapital: ' + capital + '\nPoblacion: ' + poblacion + ' habitantes\nMoneda: ' + monedas + '\nIdioma(s): ' + idiomas + '\nSuperficie: ' + superficie + '\nRegion: ' + region.trim().replace(/^,\s*/, '');

return [{
  json: {
    mensaje: inputData.mensaje,
    session_id: inputData.session_id,
    herramienta: inputData.herramienta,
    contexto_api: contexto
  }
}];

const inputData = $('Parsear Intencion').item.json;
const wiki = $json;

const titulo = wiki.title || 'Sin titulo';
const resumen = wiki.extract || 'Sin informacion disponible';
const url = (wiki.content_urls && wiki.content_urls.desktop) ? wiki.content_urls.desktop.page : '';
const resumenCorto = resumen.length > 800 ? resumen.substring(0, 800) + '...' : resumen;

const contexto = 'Tema: ' + titulo + '\nResumen: ' + resumenCorto + '\nMas info: ' + url;

return [{
  json: {
    mensaje: inputData.mensaje,
    session_id: inputData.session_id,
    herramienta: inputData.herramienta,
    contexto_api: contexto
  }
}];

const inputData = $('Parsear Intencion').item.json;
return [{
  json: {
    mensaje: inputData.mensaje,
    session_id: inputData.session_id,
    herramienta: inputData.herramienta,
    contexto_api: ''
  }
}];

const inputData = $('Validar Input').item.json;
const intencion = $('Parsear Intencion').item.json;

const agentOutput = $('Chain Generar Respuesta').item.json;
let respuesta = agentOutput.output || agentOutput.text || agentOutput.response || 'No se pudo generar respuesta.';

// Eliminar el razonamiento interno del modelo (todo lo que va antes del contenido real)
// El modelo suele terminar el razonamiento con ** o con un salto doble
const separadores = [
  /\*\*Japón[\s\S]*/,        // Buscar inicio del contenido real con **
  /\n\n([^*\n].+[\s\S]*)/,  // Primer párrafo real tras línea en blanco
];

for (const sep of separadores) {
  const match = respuesta.match(sep);
  if (match) {
    respuesta = match[0].trim();
    break;
  }
}

return [{
  json: {
    ok: true,
    session_id:        inputData.session_id,
    mensaje_usuario:   inputData.mensaje,
    respuesta:         respuesta.trim(),
    herramienta_usada: intencion.herramienta || 'ninguna',
    timestamp:         new Date().toISOString()
  }
}];

parameters.text:
=Responde SOLO con JSON, sin explicaciones, sin texto adicional, sin markdown.

Clasifica este mensaje en una de estas herramientas: clima, paises, wikipedia, ninguna.

EJEMPLOS:
Mensaje: "que tiempo hace en barcelona" → {"herramienta":"clima","parametros":{"ciudad":"barcelona"},"razon":"pregunta clima"}
Mensaje: "capital de francia" → {"herramienta":"paises","parametros":{"pais":"france"},"razon":"pregunta pais"}
Mensaje: "quien fue napoleon" → {"herramienta":"wikipedia","parametros":{"query":"napoleon"},"razon":"pregunta wikipedia"}
Mensaje: "hola como estas" → {"herramienta":"ninguna","parametros":{},"razon":"saludo"}
Mensaje: "busca en wikipedia japon" → {"herramienta":"wikipedia","parametros":{"query":"japon"},"razon":"busqueda wikipedia"}

Mensaje a clasificar: {{ $('Validar Input').item.json.mensaje }}

JSON:

=Eres un asistente virtual inteligente y amigable. Responde siempre en espanol de forma clara y concisa. Si recibes informacion de herramientas externas, usala como base para tu respuesta. Manten el contexto de la conversacion.

Informacion obtenida (herramienta: {{ $json.herramienta }}):
{{ $json.contexto_api || 'No se uso herramienta externa.' }}

Mensaje del usuario:
{{ $json.mensaje }}

