const data = $json;
const inputData = $('Parsear Intencion').item.json;

if (!data.results || data.results.length === 0) {
  throw new Error('Ciudad no encontrada: ' + (inputData.parametros.ciudad || 'desconocida'));
}

const loc = data.results[0];

return [{
  json: {
    mensaje:     inputData.mensaje,
    session_id:  inputData.session_id,
    herramienta: inputData.herramienta,
    parametros:  inputData.parametros,
    geo: {
      nombre: loc.name,
      pais:   loc.country,
      lat:    loc.latitude,
      lon:    loc.longitude
    }
  }
}];
